import axios from "axios";
import { useEffect, useRef, useState } from "react";
import { FaDownload, FaExclamationTriangle } from "react-icons/fa";
import { ToastContainer, toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";

const AppointmentsLayer = () => {
  const [userBooking, setUserBooking] = useState([]);
  const [showModal, setShowModal] = useState(false);
  const [viewBooking, setViewBooking] = useState(null);
  const [cancellingId, setCancellingId] = useState(null);
  const [cancelModal, setCancelModal] = useState(false);
  const [selectedBookingId, setSelectedBookingId] = useState(null);
  const [confirmModal, setConfirmModal] = useState(false);
  const [loading, setLoading] = useState(true);

  // Create a ref for the modal
  const modalRef = useRef(null);

  // Flatten services for pagination
  const flattenedServices = userBooking.flatMap((booking) =>
    booking.services.map((service) => ({
      ...service,
      user: booking.user,
      centre: service.centre || booking.centre, // Fallback to booking centre if service centre is missing
      consolidatedBookingId: booking.consolidatedBookingId,
    })),
  );

  // Pagination for appointments - using flattenedServices
  const [currentPage, setCurrentPage] = useState(1);
  const bookingPerPage = 10;
  const indexOfLastBooking = currentPage * bookingPerPage;
  const indexOfFirstBooking = indexOfLastBooking - bookingPerPage;
  const currentBookings = flattenedServices.slice(
    indexOfFirstBooking,
    indexOfLastBooking,
  );
  const totalPages = Math.ceil(flattenedServices.length / bookingPerPage);

  useEffect(() => {
    fetchUserBookings();
  }, []);

  const fetchUserBookings = () => {
    const token =
      localStorage.getItem("userToken") || localStorage.getItem("token");
    if (!token) {
      console.error("No token found in localStorage");
      setLoading(false);
      return;
    }

    axios
      .get(`${process.env.REACT_APP_BACKEND_URL}/api/bookings/user/me`, {
        headers: { Authorization: `Bearer ${token}` },
      })
      .then((response) => {
        setUserBooking(response.data.bookings);
        setLoading(false);
      })
      .catch((error) => {
        console.error("Error fetching bookings:", error);
        toast.error("Failed to load bookings");
        setLoading(false);
      });
  };

  const handleViewDetails = (service) => {
    setViewBooking(service);
    setShowModal(true);
  };

  const handleCancelBooking = async () => {
    if (!selectedBookingId) return;

    try {
      setCancellingId(selectedBookingId);

      await axios.patch(
        `${process.env.REACT_APP_BACKEND_URL}/api/bookings/${selectedBookingId}/status`,
        { status: "Cancelled" },
      );

      toast.success("Booking cancelled successfully");
      setTimeout(() => {
        fetchUserBookings();
      }, 3000);
    } catch (error) {
      console.error("Error cancelling booking:", error);
      toast.error(error.response?.data?.message || "Failed to cancel booking");
    } finally {
      setCancellingId(null);
      setSelectedBookingId(null);
      setCancelModal(false);
    }
  };

  const handleDownload = (bookingId) => {
    window.open(
      `${process.env.REACT_APP_BACKEND_URL}/api/invoice/${bookingId}`,
      "_blank",
    );
  };

  const handlePageChange = (pageNumber) => {
    setCurrentPage(pageNumber);
  };

  const handlePageChangeWithScroll = (page) => {
    handlePageChange(page);
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  const renderPagination = () => {
    if (flattenedServices.length === 0 || totalPages <= 1) return null;

    const pages = [];
    const maxVisible = 4;
    let startPage = Math.max(1, currentPage - Math.floor(maxVisible / 2));
    let endPage = startPage + maxVisible - 1;

    if (endPage > totalPages) {
      endPage = totalPages;
      startPage = Math.max(1, endPage - maxVisible + 1);
    }

    pages.push(
      <li
        key="first"
        className={`page-item ${currentPage === 1 ? "disabled" : ""}`}
      >
        <button
          className="page-link"
          onClick={() => currentPage !== 1 && handlePageChangeWithScroll(1)}
        >
          First
        </button>
      </li>,
    );

    pages.push(
      <li
        key="prev"
        className={`page-item ${currentPage === 1 ? "disabled" : ""}`}
      >
        <button
          className="page-link"
          onClick={() =>
            currentPage > 1 && handlePageChangeWithScroll(currentPage - 1)
          }
        >
          Prev
        </button>
      </li>,
    );

    for (let i = startPage; i <= endPage; i++) {
      pages.push(
        <li
          key={i}
          className={`page-item ${currentPage === i ? "active" : ""}`}
        >
          <button
            className="page-link"
            onClick={() => handlePageChangeWithScroll(i)}
          >
            {i}
          </button>
        </li>,
      );
    }

    pages.push(
      <li
        key="next"
        className={`page-item ${currentPage === totalPages ? "disabled" : ""}`}
      >
        <button
          className="page-link"
          onClick={() =>
            currentPage < totalPages &&
            handlePageChangeWithScroll(currentPage + 1)
          }
        >
          Next
        </button>
      </li>,
    );

    pages.push(
      <li
        key="last"
        className={`page-item ${currentPage === totalPages ? "disabled" : ""}`}
      >
        <button
          className="page-link"
          onClick={() => handlePageChangeWithScroll(totalPages)}
        >
          Last
        </button>
      </li>,
    );

    return pages;
  };

  // Handle clicks outside the modal
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (
        modalRef.current &&
        !modalRef.current.contains(event.target) &&
        showModal
      ) {
        setShowModal(false);
      }
    };

    document.addEventListener("mousedown", handleClickOutside);

    if (showModal) {
      document.body.style.overflow = "hidden";
    } else {
      document.body.style.overflow = "auto";
    }

    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
      document.body.style.overflow = "auto";
    };
  }, [showModal]);

  // Handle cancel modal click outside
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (
        modalRef.current &&
        !modalRef.current.contains(event.target) &&
        cancelModal
      ) {
        setCancelModal(false);
      }
    };

    document.addEventListener("mousedown", handleClickOutside);

    if (cancelModal) {
      document.body.style.overflow = "hidden";
    } else {
      document.body.style.overflow = "auto";
    }

    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
      document.body.style.overflow = "auto";
    };
  }, [cancelModal]);

  // Handle confirm modal click outside
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (
        modalRef.current &&
        !modalRef.current.contains(event.target) &&
        confirmModal
      ) {
        setConfirmModal(false);
      }
    };

    document.addEventListener("mousedown", handleClickOutside);

    if (confirmModal) {
      document.body.style.overflow = "hidden";
    } else {
      document.body.style.overflow = "auto";
    }

    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
      document.body.style.overflow = "auto";
    };
  }, [confirmModal]);

  const shouldDisableCancelButton = (item) => {
    if (item.status?.toLowerCase() !== "pending") return true;
    if (!item.appointmentDate || !item.appointmentTime) return true;

    const datePart = item.appointmentDate;
    const startTime = item.appointmentTime.split("-")[0].trim();

    const timeMatch = startTime.match(/(\d+):(\d+)\s*(am|pm)/i);
    if (!timeMatch) return true;

    let [_, hh, mm, period] = timeMatch;
    hh = parseInt(hh, 10);
    mm = parseInt(mm, 10);

    if (period.toLowerCase() === "pm" && hh !== 12) hh += 12;
    if (period.toLowerCase() === "am" && hh === 12) hh = 0;

    const appointmentDateTime = new Date(
      `${datePart}T${String(hh).padStart(2, "0")}:${String(mm).padStart(2, "0")}:00`,
    );
    const now = new Date();

    const timeDifferenceHours =
      (appointmentDateTime.getTime() - now.getTime()) / (1000 * 60 * 60);

    return timeDifferenceHours <= 2;
  };

  return (
    <div className="dashboard-body__content">
      <ToastContainer position="top-right" autoClose={3000} />

      {/* ========================= Statement section start =========================== */}
      <div className="row gy-4">
        <div className="col-12">
          <div className="card common-card border border-gray-five">
            <div className="card-body">
              <h2>Booking Statement</h2>

              {loading ? (
                <p>Loading bookings...</p>
              ) : flattenedServices.length > 0 ? (
                <>
                  <div className="table-responsive">
                    <table className="table text-body mt--24">
                      <thead>
                        <tr>
                          <th>Booking Id</th>
                          <th>Date</th>
                          <th>Time Slots</th>
                          <th>Patient Name</th>
                          <th>Centre Name</th>
                          <th>Centre Mobile</th>
                          <th>Service Type</th>
                          <th>Service Name</th>
                          <th>Doctor Name</th>
                          <th>Price</th>
                          <th>Status</th>
                          <th>Booking Summary</th>
                          <th>Actions</th>
                        </tr>
                      </thead>
                      <tbody>
                        {currentBookings.map((service, idx) => (
                          <tr key={service.bookingId || idx}>
                            <td data-label="BookingId">
                              {service?.bookingId || "N/A"}
                            </td>
                            <td data-label="Date">
                              {service?.appointmentDate}
                            </td>
                            <td data-label="Time">
                              {service?.appointmentTime}
                            </td>
                            <td data-label="Patient Name">
                              {service?.user?.firstName}{" "}
                              {service?.user?.lastName || ""}
                            </td>
                            <td data-label="Centre Name">
                              {service?.centre?.name || "N/A"}
                            </td>
                            <td data-label="Centre Mobile">
                              {service?.centre?.phoneNumber || "N/A"}
                            </td>
                            <td data-label="Service Type">{service?.type}</td>
                            <td data-label="Service Name">{service?.name}</td>
                            <td data-label="Doctor Name">
                              {Array.isArray(service?.doctors)
                                ? service.doctors.join(", ")
                                : service?.doctors || "N/A"}
                            </td>
                            <td data-label="Price">₹{service?.totalPrice}</td>
                            <td data-label="Status">
                              <span
                                className={`badge ${
                                  service?.status === "Confirmed"
                                    ? "bg-success"
                                    : service?.status === "Cancelled"
                                      ? "bg-danger"
                                      : service?.status === "Completed"
                                        ? "bg-success"
                                        : "bg-warning"
                                }`}
                              >
                                {service?.status === "pending"
                                  ? "Upcoming"
                                  : service?.status}
                              </span>
                            </td>
                            <td data-label="Booking Summary">
                              <button
                                className="btn btn-sm btn-info"
                                style={{
                                  display: "flex",
                                  alignItems: "center",
                                  gap: "5px",
                                }}
                                onClick={() =>
                                  handleDownload(service?.bookingId)
                                }
                              >
                                <FaDownload
                                  className="cursor-pointer text-xl"
                                  onClick={() =>
                                    handleDownload(service?.bookingId)
                                  }
                                  style={{ cursor: "pointer" }}
                                />
                                <span>Download</span>
                              </button>
                            </td>
                            <td
                              data-label="Actions"
                              style={{ display: "flex", gap: "5px" }}
                            >
                              <button
                                className="btn btn-sm btn-primary"
                                onClick={() => handleViewDetails(service)}
                              >
                                View
                              </button>
                              <button
                                className={`btn btn-sm ${
                                  service?.status === "pending"
                                    ? "btn-danger"
                                    : "btn-secondary"
                                }`}
                                onClick={async () => {
                                  if (service?.status === "pending") {
                                    if (shouldDisableCancelButton(service)) {
                                      setConfirmModal(true);
                                      return;
                                    }

                                    try {
                                      const response = await fetch(
                                        `${process.env.REACT_APP_BACKEND_URL}/api/reports/check/${service.bookingId}`,
                                      );

                                      if (response.status === 200) {
                                        toast.error(
                                          "Centre already uploaded document. You cannot cancel this booking.",
                                        );
                                      } else {
                                        setSelectedBookingId(service.bookingId);
                                        setCancelModal(true);
                                      }
                                    } catch (error) {
                                      console.error(
                                        "Error checking report:",
                                        error,
                                      );
                                      setSelectedBookingId(service.bookingId);
                                      setCancelModal(true);
                                    }
                                  }
                                }}
                                disabled={
                                  service?.status !== "pending" ||
                                  cancellingId === service.bookingId
                                }
                                title={
                                  service?.status !== "pending"
                                    ? `Cannot cancel ${service?.status} booking`
                                    : "Cancel booking"
                                }
                              >
                                {cancellingId === service.bookingId ? (
                                  <span
                                    className="spinner-border spinner-border-sm"
                                    role="status"
                                    aria-hidden="true"
                                  ></span>
                                ) : (
                                  "Cancel"
                                )}
                              </button>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>

                  {/* Pagination Section - Right Aligned with Left Showing Info */}
                  <div className="d-flex flex-column flex-md-row justify-content-between align-items-center gap-3 mt-4">
                    {/* Left side - Showing info */}
                    <div className="text-muted">
                      <span>
                        Showing {indexOfFirstBooking + 1} –{" "}
                        {Math.min(indexOfLastBooking, flattenedServices.length)}{" "}
                        of {flattenedServices.length} bookings
                      </span>
                    </div>

                    {/* Right side - Pagination */}
                    {totalPages > 1 && (
                      <nav aria-label="Booking pagination">
                        <ul className="pagination justify-content-center justify-content-md-end mb-0">
                          {renderPagination()}
                        </ul>
                      </nav>
                    )}
                  </div>
                </>
              ) : (
                <p>No bookings found.</p>
              )}
            </div>
          </div>
        </div>
      </div>
      {/* ========================= Statement section End =========================== */}

      {/* Cancel Modal */}
      {cancelModal && (
        <div
          style={{
            position: "fixed",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            backgroundColor: "rgba(0,0,0,0.4)",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            zIndex: 2000,
          }}
          onClick={() => setCancelModal(false)}
        >
          <div
            style={{
              backgroundColor: "#fff",
              padding: "25px",
              borderRadius: "10px",
              width: "400px",
              maxWidth: "90%",
              boxShadow: "0px 0px 15px rgba(0,0,0,0.3)",
              textAlign: "center",
            }}
            onClick={(e) => e.stopPropagation()}
          >
            <h5 style={{ fontWeight: "bold", marginBottom: "10px" }}>
              Cancel Booking?
            </h5>
            <p style={{ fontSize: "14px", color: "#555" }}>
              Are you sure you want to cancel this booking?
            </p>

            <div
              style={{
                display: "flex",
                gap: "10px",
                justifyContent: "center",
              }}
            >
              <button
                className="btn btn-success"
                disabled={cancellingId === selectedBookingId}
                onClick={handleCancelBooking}
              >
                {cancellingId === selectedBookingId ? "Processing..." : "Yes"}
              </button>
              <button
                className="btn btn-danger"
                disabled={cancellingId === selectedBookingId}
                onClick={() => setCancelModal(false)}
              >
                No
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Confirm Modal */}
      {confirmModal && (
        <div
          className="modal-backdrop"
          style={{
            position: "fixed",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            backgroundColor: "rgba(0,0,0,0.5)",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            zIndex: 9999,
          }}
          onClick={(e) => {
            if (e.target.className === "modal-backdrop") {
              setConfirmModal(false);
            }
          }}
        >
          <div
            className="modal-content"
            style={{
              backgroundColor: "white",
              padding: "25px",
              borderRadius: "10px",
              width: "450px",
              maxWidth: "90%",
              textAlign: "center",
            }}
            onClick={(e) => e.stopPropagation()}
          >
            <div
              style={{
                width: "60px",
                height: "60px",
                borderRadius: "50%",
                backgroundColor: "#fff3cd",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                margin: "0 auto 15px",
              }}
            >
              <FaExclamationTriangle
                style={{ fontSize: "24px", color: "#856404" }}
              />
            </div>

            <h5 style={{ marginBottom: "10px", color: "#333" }}>
              Cancellation Restricted
            </h5>

            <p
              style={{
                color: "#666",
                marginBottom: "20px",
                fontSize: "15px",
              }}
            >
              This booking cannot be cancelled as it's within 2 hours of the
              scheduled appointment.
            </p>

            <div style={{ display: "flex", justifyContent: "center" }}>
              <button
                className="btn btn-primary"
                onClick={() => setConfirmModal(false)}
                style={{
                  padding: "8px 25px",
                  fontSize: "14px",
                }}
              >
                I Understand
              </button>
            </div>
          </div>
        </div>
      )}

      {/* View Details Modal */}
      {showModal && viewBooking && (
        <div
          style={{
            position: "fixed",
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            backgroundColor: "rgba(0,0,0,0.5)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            zIndex: 1000,
            padding: "10px",
            overflowY: "auto",
          }}
          onClick={() => setShowModal(false)}
        >
          <div
            ref={modalRef}
            style={{
              backgroundColor: "#fff",
              borderRadius: "10px",
              maxWidth: "700px",
              width: "100%",
              boxShadow: "0 0 10px rgba(0,0,0,0.3)",
              position: "relative",
              overflow: "hidden",
              maxHeight: "90vh",
              overflowY: "auto",
            }}
            onClick={(e) => e.stopPropagation()}
          >
            <div
              style={{
                backgroundColor: "#3a3a3a",
                color: "#fff",
                padding: "15px 20px",
                fontSize: "18px",
                fontWeight: "bold",
                position: "sticky",
                top: 0,
                zIndex: 10,
              }}
            >
              Booking Details
              <button
                onClick={() => setShowModal(false)}
                style={{
                  position: "absolute",
                  top: "10px",
                  right: "10px",
                  background: "transparent",
                  border: "none",
                  fontSize: "22px",
                  color: "#fff",
                  cursor: "pointer",
                }}
              >
                &times;
              </button>
            </div>

            <div
              style={{
                display: "flex",
                padding: "20px",
                flexWrap: "wrap",
                gap: "20px",
              }}
            >
              {/* Left Column */}
              <div style={{ flex: "1", minWidth: "250px" }}>
                <div style={{ marginBottom: "20px" }}>
                  <p>
                    <strong style={{ color: "black" }}>Booking ID</strong>
                  </p>
                  <p>{viewBooking?.bookingId}</p>
                </div>

                <div style={{ marginBottom: "20px" }}>
                  <p>
                    <strong style={{ color: "black" }}>Appointment Date</strong>
                  </p>
                  <p>{viewBooking?.appointmentDate}</p>
                </div>

                <div style={{ marginBottom: "20px" }}>
                  <p>
                    <strong style={{ color: "black" }}>Appointment Time</strong>
                  </p>
                  <p>{viewBooking?.appointmentTime}</p>
                </div>

                <div style={{ marginBottom: "20px" }}>
                  <p>
                    <strong style={{ color: "black" }}>Centre Name</strong>
                  </p>
                  <p>{viewBooking.centre?.name || "N/A"}</p>
                </div>

                <div style={{ marginBottom: "20px" }}>
                  <p>
                    <strong style={{ color: "black" }}>Centre Email</strong>
                  </p>
                  <p>{viewBooking.centre?.email || "N/A"}</p>
                </div>

                <div style={{ marginBottom: "20px" }}>
                  <p>
                    <strong style={{ color: "black" }}>Centre Mobile</strong>
                  </p>
                  <p>{viewBooking?.centre?.phoneNumber || "N/A"}</p>
                </div>
              </div>

              {/* Right Column */}
              <div style={{ flex: "1", minWidth: "250px" }}>
                <div style={{ marginBottom: "20px" }}>
                  <p>
                    <strong style={{ color: "black" }}>Booking Type</strong>
                  </p>
                  <p>{viewBooking.type}</p>
                </div>

                <div style={{ marginBottom: "20px" }}>
                  <p>
                    <strong style={{ color: "black" }}>
                      {viewBooking?.type === "package"
                        ? "Package Name"
                        : "Service Name"}
                    </strong>
                  </p>
                  <p>{viewBooking?.name}</p>
                </div>

                <div style={{ marginBottom: "20px" }}>
                  {viewBooking?.type === "package" ? (
                    <p>
                      <strong style={{ color: "black" }}>Services Name</strong>
                    </p>
                  ) : (
                    <p>
                      <strong style={{ color: "black" }}>Category Name</strong>
                    </p>
                  )}

                  {viewBooking?.type === "package" ? (
                    viewBooking?.includedServices?.map((service, key) => (
                      <p key={key}>{service}</p>
                    ))
                  ) : (
                    <p>{viewBooking?.category}</p>
                  )}
                </div>

                <div style={{ marginBottom: "20px" }}>
                  <p>
                    <strong style={{ color: "black" }}>Doctor Name</strong>
                  </p>
                  {viewBooking?.doctors?.map((doc, index) => (
                    <p key={index}>{doc}</p>
                  ))}
                </div>

                <div style={{ marginBottom: "20px" }}>
                  <p>
                    <strong style={{ color: "black" }}>Price</strong>
                  </p>
                  <p>₹{viewBooking?.totalPrice}</p>
                </div>

                <div style={{ marginBottom: "20px" }}>
                  <p>
                    <strong style={{ color: "black" }}>Status</strong>
                  </p>
                  <p>
                    {viewBooking?.status === "pending"
                      ? "Upcoming"
                      : viewBooking?.status}
                  </p>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AppointmentsLayer;
